            ok = subprocess.run(base + ["--runtime", "codex", "--approval-receipt", str(receipt)], cwd=ROOT, capture_output=True, text=True)
            self.assertEqual(ok.returncode, 0, ok.stderr)
            self.assertTrue(json.loads(ok.stdout)["claimed"])
